#!/bin/sh
# Runs inside the build container. Never writes to /src.
# Environment:
#   FE_MAKER_BUGFIX=1  compile with the decomp's BUGFIX blocks enabled
set -eu

WORK=/work/decomp

echo "[fe-maker] Syncing decomp into working copy..."
mkdir -p "$WORK"
# --checksum without -t: only files whose content differs are copied, and they
# get a fresh mtime, so make rebuilds exactly what changed (including files
# restored after switching projects). Build outputs in the working copy are
# kept as a cache (no --delete).
rsync -rlp --checksum --exclude=.git /src/ "$WORK/"

# Project files generated by FE Maker, copied over the decomp sources.
if [ -d /overlay ]; then
    echo "[fe-maker] Applying project overlay..."
    rsync -rlp --checksum /overlay/ "$WORK/"
fi

mkdir -p "$WORK/tools/agbcc"
cp -a /opt/agbcc/. "$WORK/tools/agbcc/"
cp /rom/baserom.gba "$WORK/baserom.gba"

cd "$WORK"
echo "[fe-maker] Building tools..."
./build_tools.sh

# make's built-in CPP is "cc -E" (the Makefile's "CPP ?=" never applies).
CPP_CMD="cc -E"
if [ "${FE_MAKER_BUGFIX:-0}" = "1" ]; then
    echo "[fe-maker] BUGFIX enabled"
    CPP_CMD="cc -E -DBUGFIX=1"
fi

echo "[fe-maker] Building ROM..."
make -j"$(nproc)" CPP="$CPP_CMD" fireemblem8.gba
sha1sum -c checksum.sha1 || echo "[fe-maker] Checksum differs from the original game (expected once the project is modified)."

cp fireemblem8.gba /out/fireemblem8.gba
# Symbol addresses, for playtests (fe_maker.playtest).
cp fireemblem8.map /out/fireemblem8.map
# Symbols with their types, for patches built against this ROM (C-SkillSys prototype).
cp fireemblem8.elf /out/fireemblem8.elf
echo "[fe-maker] Done"
